"""Tables of the catalog (docs/09). The rules the database can enforce are CHECK/UNIQUE."""

from datetime import datetime
from decimal import Decimal

from sqlalchemy import BigInteger, ForeignKey, Identity, Numeric, String, func
from sqlalchemy.orm import Mapped, mapped_column, relationship

from core.db import Base

Money = Numeric(12, 2)


def _id() -> Mapped[int]:
    """Primary key: bigint generated by PostgreSQL (short, readable ids)."""
    return mapped_column(BigInteger, Identity(always=True), primary_key=True)


class Category(Base):
    """Product category, e.g. "Escritura". Unique name regardless of case."""

    __tablename__ = "categories"

    id: Mapped[int] = _id()
    name: Mapped[str] = mapped_column(String(60))
    active: Mapped[bool] = mapped_column(default=True)


class Brand(Base):
    """Product brand. Unique name regardless of case."""

    __tablename__ = "brands"

    id: Mapped[int] = _id()
    name: Mapped[str] = mapped_column(String(60))
    active: Mapped[bool] = mapped_column(default=True)


class Location(Base):
    """A store or warehouse that holds stock."""

    __tablename__ = "locations"

    id: Mapped[int] = _id()
    name: Mapped[str] = mapped_column(String(60))
    type: Mapped[str] = mapped_column(String(10))
    address: Mapped[str | None] = mapped_column(String(200))
    active: Mapped[bool] = mapped_column(default=True)


class Product(Base):
    """A product, counted in its base unit. cost is visible only with cost.view."""

    __tablename__ = "products"

    id: Mapped[int] = _id()
    sku: Mapped[str] = mapped_column(String(40))
    barcode: Mapped[str | None] = mapped_column(String(32))
    name: Mapped[str] = mapped_column(String(200))
    category_id: Mapped[int] = mapped_column(ForeignKey("categories.id"))
    brand_id: Mapped[int | None] = mapped_column(ForeignKey("brands.id"))
    base_unit: Mapped[str] = mapped_column(String(20))
    cost: Mapped[Decimal | None] = mapped_column(Money)
    active: Mapped[bool] = mapped_column(default=True)
    created_at: Mapped[datetime] = mapped_column(server_default=func.now())
    updated_at: Mapped[datetime] = mapped_column(server_default=func.now(), onupdate=func.now())

    category: Mapped[Category] = relationship(lazy="joined")
    brand: Mapped[Brand | None] = relationship(lazy="joined")
    presentations: Mapped[list["Presentation"]] = relationship(
        back_populates="product", order_by="Presentation.factor"
    )


class Presentation(Base):
    """How a product is sold (UNIDAD, CAJA...) and how many base units it holds (factor)."""

    __tablename__ = "presentations"

    id: Mapped[int] = _id()
    product_id: Mapped[int] = mapped_column(ForeignKey("products.id"))
    name: Mapped[str] = mapped_column(String(30))
    factor: Mapped[int]
    barcode: Mapped[str | None] = mapped_column(String(32))
    active: Mapped[bool] = mapped_column(default=True)

    product: Mapped[Product] = relationship(back_populates="presentations")
    price_tiers: Mapped[list["PriceTier"]] = relationship(
        order_by="PriceTier.min_quantity", cascade="all, delete-orphan"
    )


class PriceTier(Base):
    """Price of one presentation from a quantity on (VAT included, docs/03 rule 6)."""

    __tablename__ = "price_tiers"

    id: Mapped[int] = _id()
    presentation_id: Mapped[int] = mapped_column(ForeignKey("presentations.id"))
    min_quantity: Mapped[int]
    price: Mapped[Decimal] = mapped_column(Money)


class MinimumStock(Base):
    """Alert threshold for a product in a location, in base units."""

    __tablename__ = "minimum_stock"

    product_id: Mapped[int] = mapped_column(ForeignKey("products.id"), primary_key=True)
    location_id: Mapped[int] = mapped_column(ForeignKey("locations.id"), primary_key=True)
    quantity: Mapped[int]
